from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.
    """
    # Parse the cron expression
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError(f"Expected 5 cron fields, got {len(parts)}")

    minute_field, hour_field, day_field, month_field, dow_field = parts

    # Parse each field into a set of valid values
    try:
        minutes = parse_field(minute_field, 0, 59)
        hours = parse_field(hour_field, 0, 23)
        days = parse_field(day_field, 1, 31)
        months = parse_field(month_field, 1, 12)
        dows = parse_field(dow_field, 0, 7)
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid cron expression: {e}")

    # Normalize day of week (0 and 7 both mean Sunday)
    dows_normalized = set()
    for dow in dows:
        if dow == 7:
            dows_normalized.add(0)
        else:
            dows_normalized.add(dow)
    dows = dows_normalized

    # Parse the `after` timestamp
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid timestamp format: {after}")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Check up to 8 years in the future
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Some buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        # Check if current time matches the cron expression
        if matches_cron(current, minutes, hours, days, months, dows, day_field, dow_field):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)
        iterations += 1

    raise ValueError("No matching time found within 8 years")

def parse_field(field: str, min_val: int, max_val: int) -> set:
    """Parse a single cron field and return a set of valid values."""
    values = set()

    # Handle comma-separated items
    items = field.split(',')
    for item in items:
        if '/' in item:
            # Handle step values: */S or A-B/S
            range_part, step_str = item.rsplit('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")

            if step <= 0:
                raise ValueError(f"Step must be >= 1, got {step}")

            if range_part == '*':
                # */S: every S-th value starting from min_val
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            elif '-' in range_part:
                # A-B/S: every S-th value from A to B
                parts = range_part.split('-')
                if len(parts) != 2:
                    raise ValueError(f"Invalid range: {range_part}")
                try:
                    start = int(parts[0])
                    end = int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range bounds: {range_part}")

                if start > end:
                    raise ValueError(f"Invalid range: {start} > {end}")
                if start < min_val or end > max_val:
                    raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")

                for v in range(start, end + 1, step):
                    values.add(v)
            else:
                # Single value with step (unusual but valid)
                try:
                    start = int(range_part)
                except ValueError:
                    raise ValueError(f"Invalid value: {range_part}")

                if start < min_val or start > max_val:
                    raise ValueError(f"Value {start} out of bounds [{min_val}, {max_val}]")

                values.add(start)
        elif '-' in item:
            # Handle ranges: A-B
            parts = item.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range: {item}")
            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range bounds: {item}")

            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")
            if start < min_val or end > max_val:
                raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")

            for v in range(start, end + 1):
                values.add(v)
        elif item == '*':
            # Handle wildcard
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Handle single values
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds [{min_val}, {max_val}]")

            values.add(val)

    return values

def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, 
                 dows: set, day_field: str, dow_field: str) -> bool:
    """Check if a datetime matches the cron expression."""
    # Check minute, hour, month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Handle day matching with special cron logic
    day_of_month = dt.day
    day_of_week = dt.weekday()
    day_of_week = (day_of_week + 1) % 7  # Convert Python's Monday=0 to cron's Sunday=0

    day_field_unrestricted = day_field.startswith('*')
    dow_field_unrestricted = dow_field.startswith('*')

    if day_field_unrestricted and dow_field_unrestricted:
        # Both unrestricted: both must match
        return day_of_month in days and day_of_week in dows
    elif day_field_unrestricted or dow_field_unrestricted:
        # One unrestricted: either can match
        if day_field_unrestricted:
            return day_of_week in dows and day_of_month in days
        else:
            return day_of_month in days and day_of_week in dows
    else:
        # Both restricted: either can match
        return day_of_month in days or day_of_week in dows

