from typing import Tuple

def evaluate(expr: str) -> str:
    """Evaluate an arithmetic expression exactly using rational numbers."""

    # Tokenize the expression
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    # Parse and evaluate
    result, pos = parse_addition(tokens, 0)

    if pos != len(tokens):
        raise ValueError("Unexpected tokens after expression")

    # Format result
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"


def tokenize(expr: str) -> list:
    """Convert expression string into tokens."""
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif expr[i] in '+-*/^()':
            tokens.append((expr[i], expr[i]))
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]}")
    return tokens


def parse_addition(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse addition and subtraction (lowest precedence)."""
    left, pos = parse_multiplication(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_multiplication(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos


def parse_multiplication(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse multiplication and division."""
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('*', '/'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_power(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            left = left / right

    return left, pos


def parse_power(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse exponentiation (right-associative)."""
    base, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos][0] == '^':
        pos += 1
        exponent, pos = parse_power(tokens, pos)  # Right-associative

        # Exponent must be an integer
        if exponent.denominator != 1:
            raise ValueError("Exponent must be an integer")

        exp_int = exponent.numerator

        # Handle special cases
        if exp_int < 0:
            if base == 0:
                raise ZeroDivisionError("0 raised to negative power")
            base = Fraction(1) / base
            exp_int = -exp_int

        if base == 0 and exp_int == 0:
            return Fraction(1), pos

        result = base ** exp_int
        return Fraction(result), pos

    return base, pos


def parse_unary(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse unary plus and minus."""
    sign = 1

    while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
        if tokens[pos][0] == '-':
            sign *= -1
        pos += 1

    value, pos = parse_primary(tokens, pos)
    return sign * value, pos


def parse_primary(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse primary expressions (numbers and parenthesized expressions)."""
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    token = tokens[pos]

    if token[0] == 'NUM':
        return Fraction(token[1]), pos + 1
    elif token[0] == '(':
        pos += 1
        result, pos = parse_addition(tokens, pos)
        if pos >= len(tokens) or tokens[pos][0] != ')':
            raise ValueError("Unbalanced parentheses")
        return result, pos + 1
    else:
        raise ValueError(f"Expected number or '(', got {token[0]}")

