    """Tokenize the expression, returning a list of tokens."""
    tokens = []
    i = 0
    while i < len(expr):
        # Skip whitespace
        if expr[i].isspace():
            i += 1
            continue

        # Number
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        # Operator or parenthesis
        elif expr[i] in '+-*/^()':
            tokens.append(expr[i])
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        """Return the current token without consuming it."""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        """Return the current token and advance."""
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, token_type):
        """Expect a specific token and consume it."""
        token = self.consume()
        if token != token_type:
            raise ValueError(f"Expected {token_type}, got {token}")
        return token

