    """Parse multiplication/division."""
    left, pos = parse_unary(tokens, pos)

    while pos < len(tokens) and tokens[pos] in "*/":
        op = tokens[pos]
        pos += 1
        right, pos = parse_unary(tokens, pos)
        if op == "*":
            left = left * right
        else:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            left = left / right

    return left, pos


